import h5py
import numpy as np


class ReadData:
    def __init__(self, filepath):
        self.filepath = filepath

    def unit2byte(self, vecs):
        vectors = [vec.tobytes() for vec in vecs]
        return vectors

    def format(self, vecs):
        if vecs.dtype == 'uint8':
            vecs = self.unit2byte(vecs)
        # else:
        #     vecs = vecs.tolist()
        return vecs

    def read_hdf5_data(self):
        try:
            f = h5py.File(self.filepath, 'r')
            keys = list(f.keys())
            if 'embeddings' not in keys:
                raise Exception("Please make sure the file has the 'embeddings' group!")
            if 'ids' in keys:
                if f['ids'].len() != f['embeddings'].len():
                    raise Exception("Please ensure that the length of 'ids' equals that of the 'embeddings'!")
                # print(f['embeddings'][:].dtype == 'uint8')
                vectors = self.format(f['embeddings'][:])
                return vectors, f['ids'][:]
            return f['embeddings'][:], np.array([])
        except Exception as e:
            print(e)
            return "Error with {}".format(e), 400

from pymilvus_orm import connections
from pymilvus_orm.types import DataType
from pymilvus_orm.schema import FieldSchema, CollectionSchema
from pymilvus_orm.collection import Collection
from pymilvus_orm import utility
import time
import sys


class MilvusIndex:
    def __init__(self, logger, milvus_host='127.0.0.1', milvus_port=19530):
        self.logger = logger
        self.host = milvus_host
        self.port = milvus_port
        self.collection = None
        connections.connect(host=self.host, port=self.port)

    def set_collection(self, collection_name):
        try:
            if self.has_collection(collection_name):
                self.collection = Collection(name=collection_name)
            else:
                raise Exception("There has no collection named:{}".format(collection_name))
        except Exception as e:
            self.logger.error("Failed to load data to Milvus: {}".format(e))
            sys.exit(1)

    def has_collection(self, collection_name):
        try:
            return utility.has_collection(collection_name)
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

    def create_collection(self, collection_name, collection_param):
        try:
            if not self.has_collection(collection_name):
                field1 = FieldSchema(name="id", dtype=DataType.INT64, descrition="int64", is_primary=True, auto_id=False)
                field2 = FieldSchema(name="embedding", dtype=collection_param['data_type'], descrition="float vector", dim=collection_param['dimension'], is_primary=False)
                schema = CollectionSchema(fields=[field1,field2], description="collection description")
                self.collection = Collection(name=collection_name, schema=schema)   
                self.logger.debug("Create Milvus collection: {}".format(self.collection))
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

    def has_partition(self, collection_name, partition_name):
        try:
            self.set_collection(collection_name)
            return self.collection.has_partition(partition_name)
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

    def creat_partition(self, collection_name, partition_name):
        try:
            self.set_collection(collection_name)
            self.collection.create_partition(partition_name)
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

    def drop_collection(self, collection_name):
        try:
            self.set_collection(collection_name)
            self.collection.drop()
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

    def drop_partition(self, collection_name, partition_name):
        try:
            self.set_collection(collection_name)
            self.collection.drop_partition(partition_name)
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

    def insert(self, collection_name, vectors, ids, partition_name=None):
        try:
            self.set_collection(collection_name)
            data = [ids, vectors]
            mr = self.collection.insert(data=data, partition_name=partition_name)
            return "Insert success!", mr.primary_keys
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

    def count_entities(self, collection_name):
        try:
            self.set_collection(collection_name)
            num = self.collection.num_entities
            return num
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

    def get_data_type(self, collection_param):
        try:
            if collection_param['metric_type'] == 'IP':
                data_type = DataType.FLOAT_VECTOR
            elif collection_param['metric_type'] == 'L2':
                data_type = DataType.FLOAT_VECTOR
            elif collection_param['metric_type'] == 'HAMMING':
                data_type = DataType.BINARY_VECTOR
            elif collection_param['metric_type'] == 'JACCARD':
                data_type = DataType.BINARY_VECTOR
            elif collection_param['metric_type'] == 'TANIMOTO':
                data_type = DataType.BINARY_VECTOR
            elif collection_param['metric_type'] == 'SUBSTRUCTURE':
                data_type = DataType.BINARY_VECTOR
            elif collection_param['metric_type'] == 'SUPERSTRUCTURE':
                data_type = DataType.BINARY_VECTOR
            else:
                raise Exception("metric_type error: {}".format(collection_param['metric_type']))
            return data_type
        except Exception as e:
            self.logger.error(e)
            sys.exit(1)

import os
import sys

import h5py
import numpy as np
import yaml


class SaveData:
    def __init__(self, logger, data_dir, timestamp):
        self.logger = logger
        self.data_dir = data_dir
        self.timestamp = timestamp
        self.dirs = os.path.join(self.data_dir, timestamp)

    def save_hdf5_data(self, collection_name, partition_tag, vectors, ids):
        hdf5_filename = os.path.join(self.dirs, collection_name, f"{partition_tag}.h5")
        hdf5_foldername = os.path.dirname(hdf5_filename)
        if not os.path.exists(hdf5_foldername):
            os.makedirs(hdf5_foldername)

        try:
            f = h5py.File(hdf5_filename, "w")
            if type(vectors[0]) == type(b"a"):
                v = []
                for i in vectors:
                    v.append(list(i))
                data = np.array(v, dtype=np.uint8)  # save np.array and dtype=uint8
            else:
                data = np.array(vectors)

            f.create_dataset(name="embeddings", data=data)
            f.create_dataset(name="ids", data=ids)
            self.logger.debug(
                "Successfully saved data of collection: {}/partition: {} data in {}!".format(
                    collection_name, partition_tag, hdf5_filename
                )
            )
            return hdf5_filename
        except Exception as e:
            self.logger.error("Error with {}".format(e))
            sys.exit(1)

    def save_yaml(
        self,
        collection_name,
        partition_tag,
        collection_parameter,
        version,
        save_hdf5_name,
    ):
        try:
            # TODO: `dest_host` and `dest_port` can be set by parameter
            hdf2_yaml = {
                "H2M": {
                    "milvus_version": version,
                    "data_path": [save_hdf5_name],
                    "data_dir": None,
                    "dest_host": "127.0.0.1",
                    "dest_port": 19530,
                    "mode": "skip",
                    "dest_collection_name": collection_name,
                    "dest_partition_name": partition_tag,
                    "collection_parameter": collection_parameter,
                }
            }
            yaml_filename = os.path.join(self.dirs, "yamls", collection_name, f"{partition_tag}.yaml")
            yaml_foldername = os.path.dirname(yaml_filename)
            if not os.path.exists(yaml_foldername):
                os.makedirs(yaml_foldername)

            with open(yaml_filename, "w") as f:
                f.write(yaml.dump(hdf2_yaml))
            self.logger.debug(
                "Successfully saved yamls of collection: {}/partition: {} data in {}!".format(
                    collection_name, partition_tag, yaml_filename
                )
            )
        except Exception as e:
            self.logger.error("Error with {}".format(e))
            sys.exit(1)

